-- Adhunik ERP — Phase 8A Purchase Indents and Purchase Requisitions
begin;
alter table public.numbering_configurations drop constraint if exists numbering_configurations_entity_type_check;
alter table public.numbering_configurations add constraint numbering_configurations_entity_type_check check(entity_type in('EMPLOYEE','CUSTOMER','INQUIRY','ORDER','PROFORMA_INVOICE','PACKING_LIST','DISPATCH','PURCHASE_INDENT','PURCHASE_REQUISITION'));
insert into public.numbering_configurations(entity_type,prefix,padding,separator,include_financial_year) values('PURCHASE_INDENT','IND',4,'/',true),('PURCHASE_REQUISITION','PR',4,'/',true) on conflict(entity_type) do nothing;
insert into public.numbering_counters(entity_type,current_value) values('PURCHASE_INDENT',0),('PURCHASE_REQUISITION',0) on conflict do nothing;
create table public.purchase_number_counters(entity_type text not null references public.numbering_configurations(entity_type),financial_year_id uuid not null references public.financial_years(id),current_value bigint not null default 0 check(current_value>=0),updated_at timestamptz not null default now(),primary key(entity_type,financial_year_id));
create or replace function public.allocate_purchase_number(p_type text) returns text language plpgsql security definer set search_path='' as $$ declare c public.numbering_configurations%rowtype; f public.financial_years%rowtype; n bigint; begin select * into c from public.numbering_configurations where entity_type=upper(p_type) and is_active; if not found or c.entity_type not in('PURCHASE_INDENT','PURCHASE_REQUISITION') then raise exception 'Purchase numbering is not active'; end if; select * into f from public.financial_years where is_current and is_active and deleted_at is null limit 1; if not found then raise exception 'A current Financial Year is required'; end if; insert into public.purchase_number_counters values(c.entity_type,f.id,1,now()) on conflict(entity_type,financial_year_id) do update set current_value=public.purchase_number_counters.current_value+1,updated_at=now() returning current_value into n; return array_to_string(array_remove(array[nullif(c.prefix,''),f.code,lpad(n::text,c.padding,'0'),nullif(c.suffix,'')],null),c.separator); end $$;
revoke all on function public.allocate_purchase_number(text) from public,anon,authenticated;
create table public.purchase_indents(id uuid primary key default gen_random_uuid(),indent_number text not null unique,financial_year_id uuid not null references public.financial_years(id),indent_date date not null default current_date,department_id uuid not null references public.departments(id),requested_by uuid not null references auth.users(id),required_date date not null,priority text not null default 'NORMAL' check(priority in('NORMAL','URGENT')),purpose text not null,remarks text,status text not null default 'DRAFT' check(status in('DRAFT','SUBMITTED','CONVERTED_TO_PR','CANCELLED')),submitted_at timestamptz,submitted_by uuid references auth.users(id),cancelled_at timestamptz,cancelled_by uuid references auth.users(id),cancellation_reason text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.purchase_indent_items(id uuid primary key default gen_random_uuid(),indent_id uuid not null references public.purchase_indents(id) on delete cascade,line_number integer not null check(line_number>0),source_type text not null check(source_type in('ITEM_MASTER','MANUAL')),item_id uuid references public.items(id),item_code_snapshot text,item_name_snapshot text not null,description_snapshot text,hsn_code_snapshot text,unit_snapshot text not null,quantity numeric(18,3) not null check(quantity>0),required_date date,remarks text,created_at timestamptz not null default now(),unique(indent_id,line_number),check((source_type='ITEM_MASTER' and item_id is not null) or(source_type='MANUAL' and item_id is null)));
create table public.purchase_indent_activities(id uuid primary key default gen_random_uuid(),indent_id uuid not null references public.purchase_indents(id) on delete cascade,activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.purchase_requisitions(id uuid primary key default gen_random_uuid(),requisition_number text not null unique,indent_id uuid not null unique references public.purchase_indents(id),financial_year_id uuid not null references public.financial_years(id),requisition_date date not null default current_date,department_id uuid not null references public.departments(id),requested_by uuid not null references auth.users(id),required_date date not null,priority text not null check(priority in('NORMAL','URGENT')),purpose text not null,remarks text,status text not null default 'DRAFT' check(status in('DRAFT','CONFIRMED','CANCELLED')),confirmed_at timestamptz,confirmed_by uuid references auth.users(id),cancelled_at timestamptz,cancelled_by uuid references auth.users(id),cancellation_reason text,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.purchase_requisition_items(id uuid primary key default gen_random_uuid(),requisition_id uuid not null references public.purchase_requisitions(id) on delete cascade,line_number integer not null check(line_number>0),source_type text not null check(source_type in('ITEM_MASTER','MANUAL')),item_id uuid references public.items(id),item_code_snapshot text,item_name_snapshot text not null,description_snapshot text,hsn_code_snapshot text,unit_snapshot text not null,quantity numeric(18,3) not null check(quantity>0),required_date date,remarks text,created_at timestamptz not null default now(),unique(requisition_id,line_number),check((source_type='ITEM_MASTER' and item_id is not null) or(source_type='MANUAL' and item_id is null)));
create table public.purchase_requisition_activities(id uuid primary key default gen_random_uuid(),requisition_id uuid not null references public.purchase_requisitions(id) on delete cascade,activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index purchase_indents_register on public.purchase_indents(status,indent_date desc); create index purchase_indents_requester on public.purchase_indents(requested_by); create index purchase_requisitions_register on public.purchase_requisitions(status,requisition_date desc);
create or replace function public.is_erp_manager() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.erp_profiles p join public.erp_roles r on r.id=p.role_id where p.auth_user_id=auth.uid() and p.is_active and r.is_active and r.code in('ADMIN','MANAGER')) $$;
grant execute on function public.is_erp_manager() to authenticated;
create or replace function public.purchase_normalize_items(p_items jsonb) returns table(line_number integer,source_type text,item_id uuid,item_code text,item_name text,description text,hsn_code text,unit_name text,quantity numeric,required_date date,remarks text) language plpgsql security definer set search_path='' as $$ declare x jsonb;i integer:=0;m record;q numeric; begin if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one item is required'; end if; for x in select value from jsonb_array_elements(p_items) loop i:=i+1;q:=nullif(x->>'quantity','')::numeric;if q is null or q<=0 then raise exception 'Line % quantity must be greater than zero',i;end if;if x->>'source_type'='ITEM_MASTER' then select t.id,t.item_code,t.item_name,t.description,t.hsn_code,u.name unit into m from public.items t join public.units_of_measurement u on u.id=t.unit_id where t.id=(x->>'item_id')::uuid and t.is_active;if not found then raise exception 'Line % has an invalid item',i;end if;return query select i,'ITEM_MASTER'::text,m.id,m.item_code,m.item_name,coalesce(nullif(trim(x->>'description'),''),m.description),m.hsn_code,m.unit,q,nullif(x->>'required_date','')::date,nullif(trim(x->>'remarks'),'');else if nullif(trim(x->>'item_name'),'') is null or nullif(trim(x->>'unit'),'') is null then raise exception 'Line % manual Item Name and Unit are required',i;end if;return query select i,'MANUAL'::text,null::uuid,nullif(trim(x->>'item_code'),''),trim(x->>'item_name'),nullif(trim(x->>'description'),''),nullif(trim(x->>'hsn_code'),''),trim(x->>'unit'),q,nullif(x->>'required_date','')::date,nullif(trim(x->>'remarks'),'');end if;end loop;end $$;
revoke all on function public.purchase_normalize_items(jsonb) from public,anon,authenticated;
create or replace function public.save_purchase_indent(p_id uuid,p_header jsonb,p_items jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid:=p_id;fy uuid;n text;o uuid;s text;begin if not public.has_active_erp_access() then raise exception 'Unauthorized';end if;if nullif(trim(p_header->>'purpose'),'') is null or nullif(p_header->>'department_id','') is null or nullif(p_header->>'required_date','') is null then raise exception 'Department, required date and purpose are required';end if;perform 1 from public.purchase_normalize_items(p_items);if v is null then select id into fy from public.financial_years where is_current and is_active and deleted_at is null limit 1;n:=public.allocate_purchase_number('PURCHASE_INDENT');insert into public.purchase_indents(indent_number,financial_year_id,indent_date,department_id,requested_by,required_date,priority,purpose,remarks,created_by,updated_by) values(n,fy,coalesce(nullif(p_header->>'indent_date','')::date,current_date),(p_header->>'department_id')::uuid,auth.uid(),(p_header->>'required_date')::date,coalesce(nullif(p_header->>'priority',''),'NORMAL'),trim(p_header->>'purpose'),nullif(trim(p_header->>'remarks'),''),auth.uid(),auth.uid()) returning id into v;insert into public.purchase_indent_activities(indent_id,activity_type,description,created_by) values(v,'CREATED','Draft indent created',auth.uid());else select requested_by,status into o,s from public.purchase_indents where id=v for update;if not found or s<>'DRAFT' or(o<>auth.uid() and not public.is_erp_manager()) then raise exception 'Draft indent not found or unauthorized';end if;update public.purchase_indents set indent_date=coalesce(nullif(p_header->>'indent_date','')::date,indent_date),department_id=(p_header->>'department_id')::uuid,required_date=(p_header->>'required_date')::date,priority=coalesce(nullif(p_header->>'priority',''),'NORMAL'),purpose=trim(p_header->>'purpose'),remarks=nullif(trim(p_header->>'remarks'),''),updated_at=now(),updated_by=auth.uid() where id=v;delete from public.purchase_indent_items where indent_id=v;end if;insert into public.purchase_indent_items(indent_id,line_number,source_type,item_id,item_code_snapshot,item_name_snapshot,description_snapshot,hsn_code_snapshot,unit_snapshot,quantity,required_date,remarks) select v,* from public.purchase_normalize_items(p_items);return v;end $$;
create or replace function public.submit_purchase_indent(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.purchase_indents set status='SUBMITTED',submitted_at=now(),submitted_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where id=p_id and status='DRAFT' and(requested_by=auth.uid() or public.is_erp_manager());if not found then raise exception 'Draft indent not found or unauthorized';end if;insert into public.purchase_indent_activities values(default,p_id,'SUBMITTED','Indent submitted',auth.uid(),default);end $$;
create or replace function public.cancel_purchase_indent(p_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if nullif(trim(p_reason),'') is null then raise exception 'Cancellation reason is required';end if;update public.purchase_indents set status='CANCELLED',cancelled_at=now(),cancelled_by=auth.uid(),cancellation_reason=trim(p_reason),updated_at=now(),updated_by=auth.uid() where id=p_id and status in('DRAFT','SUBMITTED') and(requested_by=auth.uid() or public.is_erp_manager());if not found then raise exception 'Indent cannot be cancelled';end if;insert into public.purchase_indent_activities values(default,p_id,'CANCELLED','Indent cancelled: '||trim(p_reason),auth.uid(),default);end $$;
create or replace function public.convert_indent_to_pr(p_indent_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare h public.purchase_indents%rowtype;v uuid;fy uuid;n text;begin if not public.is_erp_manager() then raise exception 'Only Admin or Manager can convert an indent';end if;select * into h from public.purchase_indents where id=p_indent_id for update;if not found then raise exception 'Indent not found';end if;select id into v from public.purchase_requisitions where indent_id=p_indent_id;if v is not null then return v;end if;if h.status<>'SUBMITTED' then raise exception 'Only submitted indents can be converted';end if;select id into fy from public.financial_years where is_current and is_active and deleted_at is null limit 1;n:=public.allocate_purchase_number('PURCHASE_REQUISITION');insert into public.purchase_requisitions(requisition_number,indent_id,financial_year_id,department_id,requested_by,required_date,priority,purpose,remarks,created_by,updated_by) values(n,h.id,fy,h.department_id,h.requested_by,h.required_date,h.priority,h.purpose,h.remarks,auth.uid(),auth.uid()) returning id into v;insert into public.purchase_requisition_items(requisition_id,line_number,source_type,item_id,item_code_snapshot,item_name_snapshot,description_snapshot,hsn_code_snapshot,unit_snapshot,quantity,required_date,remarks) select v,line_number,source_type,item_id,item_code_snapshot,item_name_snapshot,description_snapshot,hsn_code_snapshot,unit_snapshot,quantity,required_date,remarks from public.purchase_indent_items where indent_id=h.id;update public.purchase_indents set status='CONVERTED_TO_PR',updated_at=now(),updated_by=auth.uid() where id=h.id;insert into public.purchase_indent_activities values(default,h.id,'CONVERTED_TO_PR','Converted to '||n,auth.uid(),default);insert into public.purchase_requisition_activities values(default,v,'CREATED','Created from '||h.indent_number,auth.uid(),default);return v;end $$;
create or replace function public.save_purchase_requisition(p_id uuid,p_header jsonb,p_items jsonb) returns uuid language plpgsql security definer set search_path='' as $$ begin if not public.is_erp_manager() then raise exception 'Only Admin or Manager can edit a requisition';end if;if nullif(trim(p_header->>'purpose'),'') is null or nullif(p_header->>'department_id','') is null or nullif(p_header->>'required_date','') is null then raise exception 'Department, required date and purpose are required';end if;perform 1 from public.purchase_normalize_items(p_items);perform 1 from public.purchase_requisitions where id=p_id and status='DRAFT' for update;if not found then raise exception 'Draft requisition not found';end if;update public.purchase_requisitions set requisition_date=coalesce(nullif(p_header->>'requisition_date','')::date,requisition_date),department_id=(p_header->>'department_id')::uuid,required_date=(p_header->>'required_date')::date,priority=coalesce(nullif(p_header->>'priority',''),'NORMAL'),purpose=trim(p_header->>'purpose'),remarks=nullif(trim(p_header->>'remarks'),''),updated_at=now(),updated_by=auth.uid() where id=p_id;delete from public.purchase_requisition_items where requisition_id=p_id;insert into public.purchase_requisition_items(requisition_id,line_number,source_type,item_id,item_code_snapshot,item_name_snapshot,description_snapshot,hsn_code_snapshot,unit_snapshot,quantity,required_date,remarks) select p_id,* from public.purchase_normalize_items(p_items);insert into public.purchase_requisition_activities values(default,p_id,'UPDATED','Draft requisition updated',auth.uid(),default);return p_id;end $$;
create or replace function public.confirm_purchase_requisition(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_erp_manager() then raise exception 'Only Admin or Manager can confirm a requisition';end if;update public.purchase_requisitions set status='CONFIRMED',confirmed_at=now(),confirmed_by=auth.uid(),updated_at=now(),updated_by=auth.uid() where id=p_id and status='DRAFT';if not found then raise exception 'Draft requisition not found';end if;insert into public.purchase_requisition_activities values(default,p_id,'CONFIRMED','Purchase requisition confirmed',auth.uid(),default);end $$;
create or replace function public.cancel_purchase_requisition(p_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_erp_manager() or nullif(trim(p_reason),'') is null then raise exception 'Manager access and cancellation reason are required';end if;update public.purchase_requisitions set status='CANCELLED',cancelled_at=now(),cancelled_by=auth.uid(),cancellation_reason=trim(p_reason),updated_at=now(),updated_by=auth.uid() where id=p_id and status in('DRAFT','CONFIRMED');if not found then raise exception 'Requisition cannot be cancelled';end if;insert into public.purchase_requisition_activities values(default,p_id,'CANCELLED','Requisition cancelled: '||trim(p_reason),auth.uid(),default);end $$;
grant execute on function public.save_purchase_indent(uuid,jsonb,jsonb),public.submit_purchase_indent(uuid),public.cancel_purchase_indent(uuid,text),public.convert_indent_to_pr(uuid),public.save_purchase_requisition(uuid,jsonb,jsonb),public.confirm_purchase_requisition(uuid),public.cancel_purchase_requisition(uuid,text) to authenticated;
alter table public.purchase_number_counters enable row level security;alter table public.purchase_indents enable row level security;alter table public.purchase_indent_items enable row level security;alter table public.purchase_indent_activities enable row level security;alter table public.purchase_requisitions enable row level security;alter table public.purchase_requisition_items enable row level security;alter table public.purchase_requisition_activities enable row level security;
create policy "ERP users read visible indents" on public.purchase_indents for select to authenticated using(public.has_active_erp_access() and(requested_by=auth.uid() or public.is_erp_manager()));create policy "ERP users read visible indent items" on public.purchase_indent_items for select to authenticated using(exists(select 1 from public.purchase_indents h where h.id=indent_id and(h.requested_by=auth.uid() or public.is_erp_manager())));create policy "ERP users read visible indent activity" on public.purchase_indent_activities for select to authenticated using(exists(select 1 from public.purchase_indents h where h.id=indent_id and(h.requested_by=auth.uid() or public.is_erp_manager())));create policy "Managers read requisitions" on public.purchase_requisitions for select to authenticated using(public.is_erp_manager());create policy "Managers read requisition items" on public.purchase_requisition_items for select to authenticated using(public.is_erp_manager());create policy "Managers read requisition activity" on public.purchase_requisition_activities for select to authenticated using(public.is_erp_manager());
grant select on public.purchase_indents,public.purchase_indent_items,public.purchase_indent_activities,public.purchase_requisitions,public.purchase_requisition_items,public.purchase_requisition_activities to authenticated;revoke all on public.purchase_number_counters from public,anon,authenticated;revoke insert,update,delete on public.purchase_indents,public.purchase_indent_items,public.purchase_indent_activities,public.purchase_requisitions,public.purchase_requisition_items,public.purchase_requisition_activities from authenticated;
commit;